Definition pf_flows (x0 x8 : word) (sp : word) (E : Z) : list cell :=
  [C8 x0; C8 x8; C8 (Z_to_bv 64 (bv_unsigned sp + 152)); C8 (wz 3); C8 (shw E); C8 (shw (E + 16)); C8 (wz (E + 16))].

Definition pf_fctx (m m1 : mem) (sp : word) (SV : list cell) (B E L lo shi : Z) (p0 : Z) (bs : list byte)
    (x0 x8 : word) (tlc tmp : list cell) (pv nlen : Z) (vlc : list cell) (bsz : Z) (bb : list byte) (ecs : list cell) (g : bool) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -192) (pf_flows x0 x8 sp E)
  /\ rw_cells bsegs m1 (bv_unsigned sp + -136) tlc
  /\ rw_cells bsegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells bsegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells bsegs m1 (bv_unsigned sp + 144) [C8 (wz pv)]
  /\ rw_cells bsegs m1 (bv_unsigned sp + 168) [C8 (wz p0); C8 (wz nlen)]
  /\ rw_cells bsegs m1 (bv_unsigned sp + 152) vlc
  /\ rw_cells bsegs m1 B [C8 (wz bsz)]
  /\ u8arr bsegs m1 (B + 8) bb /\ length bb = 4096%nat
  /\ rw_cells bsegs m1 E ecs
  /\ bytes_at bsegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ APfTab m1
  /\ AHttpCat m1 g
  /\ stk bsegs m1 lo (bv_unsigned sp + -192)
  /\ munch (pf_W lo sp B E) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ pf_side m B E p0 (Z.of_nat (length bs)) lo shi.
