Lemma pf_fctx_ctx : forall m m1 sp SV B E L lo shi p0 bs x0 x8 tlc tmp pv nlen vlc bsz bb ecs g,
  pf_fctx m m1 sp SV B E L lo shi p0 bs x0 x8 tlc tmp pv nlen vlc bsz bb ecs g ->
  pf_ctx m m1 sp SV B E L lo shi p0 bs (pf_lows x0 x8 (Z_to_bv 64 (bv_unsigned sp + 152)) (wz 3) (shw E) E) tlc tmp pv
         [C8 (wz p0); C8 (wz nlen)] vlc bsz bb ecs g.
