(* [comment removed for export] *)
Lemma win_slice : forall m it0 bs a k, bytes_at bsegs m it0 bs -> it0 <= a -> 0 <= k -> a + k <= it0 + Z.of_nat (length bs) ->
  bytes_at bsegs m a (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs))
  /\ length (firstn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) = Z.to_nat k.
Proof.
  intros m it0 bs a k WIN H1 H2 H3.
  destruct (win_suffix _ _ _ a WIN ltac:(lia)) as [WS LS].
  rewrite <- (firstn_skipn (Z.to_nat k) (skipn (Z.to_nat (a - it0)) bs)) in WS. apply bytes_at_app in WS. destruct WS as [W1 _].
  split; [exact W1|]. rewrite firstn_length_le; [reflexivity|]. rewrite length_skipn. lia.
Qed.

Lemma rw_cells_CB_length : forall m A n bs, rw_cells bsegs m A [CB n bs] -> length bs = n.
Proof. intros m A n bs [[WF _] _]. cbn in WF. tauto. Qed.

