Definition PF_L6_AT (M : Z) : Prop :=
  forall (p : Z) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a7
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (x0 x8 : word) (tlc tmp : list cell) (nlen : Z) (vlc : list cell) (bsz : Z) (bb : list byte) (g : bool),
  pf_fctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
          x0 x8 tlc tmp p nlen vlc bsz bb (ErrCodeCells E0) g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> cells_size tlc = 8%nat -> cells_size tmp = 24%nat -> cells_size vlc = 16%nat ->
  p <= L -> p0 + 2 <= p -> 1 <= nlen -> p0 + nlen < p -> bsz + nlen + 3 <= p - p0 -> L - p < M ->
  evt bsegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz E) (Z_to_bv 64 (-1)) a0 a1 a2 a3 (wz (nbw B)) (wz 2) (wz 9) a7
              (wz B) (wz (B + 8)) (Z_to_bv 64 (bv_unsigned sp + 144)) (wz L) (wz 32) (wz p) (wz p) (wz 2147450880) (shw B)
              (shw (bv_unsigned sp + 144)) t3 t4 t5 t6)
        F (Z_to_bv 64 0xd4d8c) fc None m1 (seg_rom bsegs)).

